function decompose(series, period){
  var n=series.length;
  if(n<2*period) return null;
  var trend=new Array(n).fill(null);
  var w=(period%2===1)? period : period+1;
  var half=Math.floor(w/2);
  for(var i=0;i<n;i++){ var s=0,cnt=0; for(var j=i-half;j<=i+half;j++){ if(j>=0&&j<n){ var wj=1; if(w!==period && (j===i-half||j===i+half)) wj=0.5; s+=series[j]*wj; cnt+=wj; } } if(cnt>0) trend[i]=s/cnt; }
  if(period%2===0){ var t2=new Array(n).fill(null); for(var i=0;i<n;i++){ var a=(i>0&&trend[i-1]!=null)?trend[i-1]:null; var bb=trend[i]; if(a!=null&&bb!=null) t2[i]=(a+bb)/2; } trend=t2; }
  var detr=new Array(n).fill(0);
  for(var i=0;i<n;i++){ if(trend[i]!=null) detr[i]=series[i]-trend[i]; }
  var sums=new Array(period).fill(0), counts=new Array(period).fill(0);
  for(var i=0;i<n;i++){ if(trend[i]!=null){ var p=i%period; sums[p]+=detr[i]; counts[p]++; } }
  var seasAvg=new Array(period).fill(0);
  for(var p=0;p<period;p++){ if(counts[p]>0) seasAvg[p]=sums[p]/counts[p]; }
  var seasMean=seasAvg.reduce(function(a,b){return a+b;},0)/period;
  var seasonal=new Array(n).fill(0);
  for(var i=0;i<n;i++) seasonal[i]=seasAvg[i%period]-seasMean;
  var resid=new Array(n).fill(0);
  for(var i=0;i<n;i++){ if(trend[i]!=null) resid[i]=series[i]-trend[i]-seasonal[i]; }
  return {trend:trend, seasonal:seasonal, resid:resid};
}
var EXPORTS={decompose:decompose};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SeasonalDecomposeForgePure = EXPORTS; }
